import React from 'react';
import { Image, View } from 'react-native';
import { dark } from './theme';
import { t } from './i18n';

// The GotMyGame lettering as artwork (silver chrome "GotMy", glossy purple "Game", dark outline), generated by scripts/brand/render.mjs.
// The name alone works on any surface because the lettering carries its own outline; the tagline lockup comes in a light and a dark version.
const NAME = { src: require('../assets/brand/wordmark.png'), ratio: 1651 / 339 };
const LOCKUP = { src: require('../assets/brand/wordmark-tagline.png'), ratio: 1676 / 518 };
const LOCKUP_DARK = { src: require('../assets/brand/wordmark-tagline-dark.png'), ratio: 1676 / 518 };

/**
 * "GotMyGame" as in the logo. `width` is the artwork width in points; `tagline` adds the swoosh and "THE SPORTSVERSE".
 * `onDark` says the lockup sits on a dark panel (a gradient hero, the dark theme) so the tagline is light.
 */
export function Wordmark({ width = 140, tagline = false, onDark, align = 'flex-start', style, accessibilityRole }) {
  const a = tagline ? (onDark ?? dark ? LOCKUP_DARK : LOCKUP) : NAME;
  const label = tagline ? `GotMyGame, ${t('brand.tagline')}` : 'GotMyGame';
  return (
    <View accessible accessibilityRole={accessibilityRole ?? 'header'} accessibilityLabel={label} style={[{ alignItems: align }, style]}>
      <Image source={a.src} accessible={false} style={{ width, height: width / a.ratio }} resizeMode="contain" />
    </View>
  );
}
